int fd = 5; // Target descriptor
int status;

status = close(fd);

if (status == -1) {
    if (errno == EBADF) {
        // fd is not valid or not open
    } else if (errno == EINTR) {
        // Interrupted by signal
    }
    perror("close failed");
}

// Upon successful return (0), fd is invalid
// and resources may be freed.
